import { analyze, extractive, mins, readLabel } from './analysis.js';
import { summarize } from './gemini.js';

// config.js is generated by build.mjs from your .env file (or the GitHub secret).
// If it's missing, the app still works: you can paste a key in the "API key" panel.
let CFG = {};
try { CFG = (await import('../config.js')).default || {}; } catch (e) { /* no built-in key */ }

const $ = id => document.getElementById(id);
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = n => Number(n).toLocaleString('en-US');
const store = {
  get: k => { try { return localStorage.getItem(k); } catch (e) { return null; } },
  set: (k, v) => { try { v == null ? localStorage.removeItem(k) : localStorage.setItem(k, v); } catch (e) { /* storage blocked */ } },
};
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

const SAMPLE = `Artificial intelligence is changing the way students learn and work. Tools that can read, write and summarize text are now available to anyone with a phone or a laptop. These tools can help a student understand a long reading assignment in minutes, find the main ideas of a research article, or check whether an essay is clear and easy to read.

However, artificial intelligence also brings new responsibilities. Students must still read critically, because a summary can miss important details or misunderstand the author's point. Teachers worry that some students will rely on AI instead of building their own reading and writing skills. Schools are now writing guidelines that explain when AI tools may be used and how their use should be disclosed.

Used well, text analysis and summarization can save time and improve understanding. The best approach is to treat AI as a study partner: let it point out key ideas and difficult passages, then return to the original text to confirm what it says.`;

let last = {}, busy = false;

/* ---------- buddy (the mascot) ---------- */
const MOUTH = {
  idle: ['M80 124 Q96 142 112 124', 'none'],
  think: ['M88 128 Q96 118 104 128 Q96 138 88 128 Z', '#18181B'],
  happy: ['M76 120 Q96 154 116 120 Z', '#18181B'],
  sad: ['M80 136 Q96 122 112 136', 'none'],
};
function mood(state, text) {
  const [d, fill] = MOUTH[state] || MOUTH.idle;
  $('mouth').setAttribute('d', d);
  $('mouth').setAttribute('fill', fill);
  $('buddyWrap').classList.toggle('thinking', state === 'think');
  $('buddyWrap').classList.remove('happy');
  if (state === 'happy') { void $('buddyWrap').offsetWidth; $('buddyWrap').classList.add('happy'); }
  if (text) $('bubble').textContent = text;
}
window.addEventListener('pointermove', e => {
  const r = $('buddy').getBoundingClientRect();
  const s = r.width / 220;
  [['pupilL', 72], ['pupilR', 120]].forEach(([id, cx]) => {
    const ex = r.left + cx * s, ey = r.top + 90 * s;
    const dx = e.clientX - ex, dy = e.clientY - ey, d = Math.hypot(dx, dy) || 1;
    const k = Math.min(6, d / 40);
    $(id).style.transform = `translate(${(dx / d * k).toFixed(1)}px, ${(dy / d * k).toFixed(1)}px)`;
  });
}, { passive: true });

/* ---------- toast & confetti ---------- */
function toast(msg) {
  const t = $('toast');
  t.textContent = msg;
  t.classList.add('on');
  clearTimeout(toast.t);
  toast.t = setTimeout(() => t.classList.remove('on'), 2200);
}
function confetti() {
  if (reduceMotion) return;
  const c = $('confetti'), ctx = c.getContext('2d');
  const W = c.width = innerWidth * devicePixelRatio, H = c.height = innerHeight * devicePixelRatio;
  const colors = ['#FFD23F', '#FF7AA8', '#4BE3AC', '#6CCBFF', '#FF9F45', '#B9A2FF'];
  const bits = Array.from({ length: 140 }, () => ({
    x: W / 2 + (Math.random() - .5) * W * .3, y: H * .35,
    vx: (Math.random() - .5) * 26 * devicePixelRatio, vy: (-Math.random() * 22 - 8) * devicePixelRatio,
    s: (6 + Math.random() * 8) * devicePixelRatio, r: Math.random() * 6, vr: (Math.random() - .5) * .4,
    c: colors[Math.floor(Math.random() * colors.length)],
  }));
  let frame = 0;
  (function tick() {
    ctx.clearRect(0, 0, W, H);
    bits.forEach(b => {
      b.vy += .9 * devicePixelRatio; b.vx *= .985; b.x += b.vx; b.y += b.vy; b.r += b.vr;
      ctx.save(); ctx.translate(b.x, b.y); ctx.rotate(b.r);
      ctx.fillStyle = b.c; ctx.strokeStyle = '#18181B'; ctx.lineWidth = 1.5 * devicePixelRatio;
      ctx.fillRect(-b.s / 2, -b.s / 3, b.s, b.s * .66); ctx.strokeRect(-b.s / 2, -b.s / 3, b.s, b.s * .66);
      ctx.restore();
    });
    if (++frame < 110) requestAnimationFrame(tick); else ctx.clearRect(0, 0, W, H);
  })();
}

/* ---------- API key handling ---------- */
// One or more built-in keys (main key first, then backups), from .env or GitHub secrets.
const BUILT_KEYS = [...new Set([...(Array.isArray(CFG.GEMINI_API_KEYS) ? CFG.GEMINI_API_KEYS : []), CFG.GEMINI_API_KEY]
  .map(k => String(k || '').trim()).filter(Boolean))];
const BUILT_KEY = BUILT_KEYS[0] || '';
let userKey = store.get('tl_gemini_key') || '';
const getKey = () => userKey || BUILT_KEY;
// A pasted key is used on its own; otherwise all built-in keys take turns.
const getKeys = () => userKey ? [userKey] : BUILT_KEYS;
function keyUI() {
  const ok = !!getKey();
  $('keyDot').classList.toggle('ok', ok);
  $('keyLabel').textContent = userKey ? 'Your key' : 'Add API key';
  // With a built-in key, visitors never need their own: hide the top button and
  // keep only a small optional link in the footer. Show the button again only if
  // someone has chosen to paste their own key (so they can see and remove it).
  $('keyBtn').classList.toggle('hide', !!BUILT_KEY && !userKey);
  $('ownKeyLink').classList.toggle('hide', !BUILT_KEY);
  $('keyTitle').textContent = BUILT_KEY ? 'Your own Gemini key (optional)' : 'Gemini API key';
  $('keyStatus').textContent = BUILT_KEY
    ? 'You don\'t need a key: TextLens already has one and works as it is. This is only for people who would rather use their own free Gemini key.'
    : 'No key is built into this site yet. Paste a Gemini API key to switch on the AI summary.';
  $('remember').checked = !!store.get('tl_gemini_key');
}
function togglePanel(open) {
  const p = $('keyPanel'), show = open ?? p.classList.contains('hide');
  p.classList.toggle('hide', !show);
  $('keyBtn').setAttribute('aria-expanded', show);
  if (show) $('keyInput').focus();
}
$('keyBtn').onclick = () => togglePanel();
$('ownKeyLink').onclick = () => { togglePanel(true); $('keyPanel').scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' }); };
$('keySave').onclick = () => {
  const v = $('keyInput').value.trim();
  if (!v) { toast('Paste a key first'); return; }
  userKey = v;
  store.set('tl_gemini_key', $('remember').checked ? v : null);
  $('keyInput').value = '';
  keyUI(); togglePanel(false);
  mood('happy', 'Key received! Now hit “Analyze it!”');
};
$('remember').onchange = () => { if (userKey) store.set('tl_gemini_key', $('remember').checked ? userKey : null); };
$('keyForget').onclick = () => { userKey = ''; store.set('tl_gemini_key', null); keyUI(); if (BUILT_KEY) togglePanel(false); toast(BUILT_KEY ? 'Back to the built-in key' : 'Pasted key forgotten'); };
keyUI();

/* ---------- input: tabs, file, sample ---------- */
const tab = t => {
  const pdf = t === 'pdf';
  $('tabText').setAttribute('aria-selected', !pdf);
  $('tabPdf').setAttribute('aria-selected', pdf);
  $('paneText').classList.toggle('hide', pdf);
  $('panePdf').classList.toggle('hide', !pdf);
};
$('tabText').onclick = () => tab('text');
$('tabPdf').onclick = () => tab('pdf');
$('drop').onclick = () => $('file').click();
$('drop').onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); $('file').click(); } };
['dragover', 'dragenter'].forEach(ev => $('drop').addEventListener(ev, e => { e.preventDefault(); $('drop').classList.add('over'); }));
['dragleave', 'drop'].forEach(ev => $('drop').addEventListener(ev, e => { e.preventDefault(); $('drop').classList.remove('over'); }));
$('drop').addEventListener('drop', e => { const f = e.dataTransfer.files[0]; if (f) loadFile(f); });
$('file').onchange = e => { const f = e.target.files[0]; if (f) loadFile(f); };
$('sampleBtn').onclick = () => { $('txt').value = SAMPLE; run(false); mood('idle', 'Sample loaded. Tap “Analyze it!”'); };

async function loadFile(f) {
  $('fileInfo').textContent = 'Reading ' + f.name + '…';
  mood('think', 'Opening your file…');
  try {
    let text = '';
    if (/\.pdf$/i.test(f.name) || f.type === 'application/pdf') {
      if (!window.pdfjsLib) throw new Error('the PDF reader did not load. Check your internet connection.');
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
      const pdf = await pdfjsLib.getDocument({ data: await f.arrayBuffer() }).promise;
      const parts = [];
      for (let p = 1; p <= pdf.numPages; p++) {
        const c = await (await pdf.getPage(p)).getTextContent();
        let s = '';
        for (const it of c.items) s += it.str + (it.hasEOL ? '\n' : ' ');
        parts.push(s.replace(/[ \t]+/g, ' ').trim());
        $('fileInfo').textContent = `Reading ${f.name}: page ${p} of ${pdf.numPages}`;
      }
      text = parts.join('\n\n');
      if (!text.replace(/\s/g, '')) throw new Error('no text found. This PDF may be a scanned image and needs OCR first.');
      $('fileInfo').textContent = `Loaded ${f.name} (${pdf.numPages} page${pdf.numPages > 1 ? 's' : ''}).`;
    } else {
      text = await f.text();
      $('fileInfo').textContent = `Loaded ${f.name}.`;
    }
    $('txt').value = text;
    tab('text');
    run(true);
  } catch (err) {
    $('fileInfo').textContent = 'Could not read the file: ' + err.message;
    mood('sad', 'That file was hard to chew.');
  }
}

/* ---------- rendering ---------- */
const DOODLES = [
  '<svg viewBox="0 0 40 40"><path d="M20 2l5 12 13 1-10 9 3 13-11-7-11 7 3-13L2 15l13-1z" fill="#18181B"/></svg>',
  '<svg viewBox="0 0 40 40"><path d="M3 26c6-12 10 8 17-4s11 6 17-6" stroke="#18181B" stroke-width="5" fill="none" stroke-linecap="round"/></svg>',
  '<svg viewBox="0 0 40 40"><circle cx="20" cy="20" r="7" fill="#18181B"/><path d="M20 2v8M20 30v8M2 20h8M30 20h8M7 7l6 6M27 27l6 6M33 7l-6 6M13 27l-6 6" stroke="#18181B" stroke-width="4" stroke-linecap="round"/></svg>',
  '<svg viewBox="0 0 40 40"><circle cx="20" cy="20" r="16" fill="none" stroke="#18181B" stroke-width="5"/><path d="M20 10v11l7 5" stroke="#18181B" stroke-width="5" fill="none" stroke-linecap="round"/></svg>',
];
const TILE_COLORS = ['var(--yellow)', 'var(--pink)', 'var(--mint)', 'var(--sky)'];
const TILT = [-1.6, 1.2, -1, 1.6];
const CLOUD_COLORS = ['var(--c1)', 'var(--c2)', 'var(--c3)', 'var(--c4)', 'var(--c5)', 'var(--ink)'];
const hash = s => [...s].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) >>> 0, 7);

function gauge(fre) {
  const cx = 120, cy = 124, r = 92;
  const pt = s => { const a = Math.PI - s / 100 * Math.PI; return [cx + r * Math.cos(a), cy - r * Math.sin(a)]; };
  const arc = (s0, s1) => { const [x0, y0] = pt(s0), [x1, y1] = pt(s1); return `M${x0.toFixed(1)} ${y0.toFixed(1)} A${r} ${r} 0 0 1 ${x1.toFixed(1)} ${y1.toFixed(1)}`; };
  return `<svg class="gauge" viewBox="0 0 240 150" role="img" aria-label="Reading ease ${fre.toFixed(0)} out of 100">
    <path d="${arc(0, 100)}" stroke="#18181B" stroke-width="32" fill="none"/>
    <path d="${arc(0.6, 30)}" stroke="#FF7AA8" stroke-width="24" fill="none"/>
    <path d="${arc(30, 60)}" stroke="#FFD23F" stroke-width="24" fill="none"/>
    <path d="${arc(60, 99.4)}" stroke="#4BE3AC" stroke-width="24" fill="none"/>
    <g class="needle" id="needle"><path d="M${cx} ${cy - 7} L${cx - 78} ${cy} L${cx} ${cy + 7} Z" fill="#18181B"/></g>
    <circle cx="${cx}" cy="${cy}" r="13" fill="#FF9F45" stroke="#18181B" stroke-width="5"/>
    <text x="22" y="146" font-family="Fredoka,sans-serif" font-weight="600" font-size="14" fill="currentColor">Hard</text>
    <text x="218" y="146" text-anchor="end" font-family="Fredoka,sans-serif" font-weight="600" font-size="14" fill="currentColor">Easy</text>
  </svg>`;
}

function face(sentiment) {
  const s = String(sentiment || '').toLowerCase();
  const [fill, mouth] = {
    positive: ['#4BE3AC', 'M17 31 Q27 42 37 31'],
    negative: ['#FF7AA8', 'M17 38 Q27 29 37 38'],
    mixed: ['#FF9F45', 'M16 35 q5 -5 10 0 t10 0'],
  }[s] || ['#FFD23F', 'M18 35 H36'];
  return `<svg class="face" viewBox="0 0 54 54" aria-hidden="true"><circle cx="27" cy="27" r="23" fill="${fill}" stroke="#18181B" stroke-width="4"/><circle cx="20" cy="23" r="3.6" fill="#18181B"/><circle cx="34" cy="23" r="3.6" fill="#18181B"/><path d="${mouth}" stroke="#18181B" stroke-width="3.6" fill="none" stroke-linecap="round"/></svg>`;
}

function renderLocal(a) {
  $('live').textContent = `${fmt(a.words)} words · ${fmt(a.chars)} characters`;

  const tiles = [['Words', fmt(a.words)], ['Unique words', fmt(a.unique)], ['Sentences', fmt(a.sents)], ['Reading time', mins(a.readMin)]];
  $('tiles').innerHTML = tiles.map(([l, v], i) =>
    `<div class="tile" style="background:${TILE_COLORS[i]};transform:rotate(${TILT[i]}deg)">${DOODLES[i]}<div class="v">${esc(v)}</div><div class="l">${esc(l)}</div></div>`).join('');

  const fre = Math.max(0, Math.min(100, a.fre));
  const col = fre >= 60 ? 'var(--mint)' : fre >= 30 ? 'var(--yellow)' : 'var(--pink)';
  $('read').innerHTML = a.words
    ? gauge(fre) + `<div class="read-score"><div class="big">${fre.toFixed(0)} / 100</div><span class="lab" style="background:${col}">${readLabel(fre)}</span>
       <p class="note">Flesch Reading Ease · about grade ${Math.max(0, a.fk).toFixed(1)} (Flesch–Kincaid). Built for English text.</p></div>`
    : '<p class="empty">Nothing to read yet.</p>';
  const needle = $('needle');
  if (needle) requestAnimationFrame(() => requestAnimationFrame(() => { needle.style.transform = `rotate(${(fre * 1.8).toFixed(1)}deg)`; }));

  if (a.cloud.length) {
    const max = a.cloud[0][1], min = a.cloud[a.cloud.length - 1][1];
    const words = [...a.cloud].sort((x, y) => hash(x[0]) - hash(y[0]));
    $('cloud').innerHTML = words.map(([w, c]) => {
      const size = 16 + (max === min ? 12 : (c - min) / (max - min) * 30);
      const h = hash(w), rot = h % 5 === 0 ? -6 : h % 7 === 0 ? 5 : 0;
      return `<span title="${esc(w)}: ${c}" style="font-size:${size.toFixed(0)}px;color:${CLOUD_COLORS[h % CLOUD_COLORS.length]};transform:rotate(${rot}deg)">${esc(w)}</span>`;
    }).join('');
  } else $('cloud').innerHTML = '<p class="empty">Your word cloud will grow here.</p>';

  const top = a.top[0] ? a.top[0][1] : 1;
  const barCols = ['var(--yellow)', 'var(--pink)', 'var(--mint)', 'var(--sky)', 'var(--orange)', 'var(--lilac)'];
  $('board').innerHTML = a.top.length ? a.top.map(([w, c], i) =>
    `<li><span class="rank">${i + 1}</span><span class="w" title="${esc(w)}">${esc(w)}</span><span class="t"><i style="width:${(c / top * 100).toFixed(1)}%;background:${barCols[i % barCols.length]};animation-delay:${i * 50}ms"></i></span><span class="c">${c}</span></li>`).join('')
    : '<li class="empty">No words yet.</li>';

  const facts = [['Paragraphs', fmt(a.paras)], ['Characters', fmt(a.chars)], ['Without spaces', fmt(a.charsNoSp)], ['Avg. word length', a.avgWord.toFixed(1) + ' letters'], ['Avg. sentence', a.avgSent.toFixed(1) + ' words'], ['Speaking time', mins(a.speakMin)], ['Word variety', Math.round(a.diversity * 100) + '%'], ['Longest word', a.longest[0] || '–']];
  $('facts').innerHTML = facts.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('');

  $('pairs').innerHTML = a.bigrams.length ? a.bigrams.map(([p, c]) => `<span>${esc(p)}<em>×${c}</em></span>`).join('') : '<p class="empty">No pair shows up twice yet.</p>';

  const len = document.querySelector('input[name=len]:checked').value;
  const ex = extractive(a, { short: 2, medium: 3, long: 5 }[len]);
  $('ext').innerHTML = ex.length ? '<p>' + ex.map(esc).join(' ') + '</p>' : '<p class="empty">Nothing yet.</p>';
}

function renderAI(j) {
  last.ai = j;
  const paras = String(j.summary || '').split(/\n\s*\n/).filter(Boolean);
  const pts = Array.isArray(j.key_points) ? j.key_points : [];
  $('summary').innerHTML = `<div class="pop">${paras.map(p => `<p>${esc(p)}</p>`).join('')}${pts.length ? `<h3>Key points</h3><ol class="points">${pts.map(k => `<li><span>${esc(k)}</span></li>`).join('')}</ol>` : ''}</div>`;
  const sc = { positive: 'var(--mint)', negative: 'var(--pink)', mixed: 'var(--orange)' }[String(j.sentiment).toLowerCase()] || 'var(--yellow)';
  $('mood').innerHTML = face(j.sentiment) + [
    j.sentiment && `<span class="tag" style="background:${sc}">Feels ${esc(j.sentiment)}</span>`,
    j.tone && `<span class="tag" style="background:var(--sky)">Tone: ${esc(j.tone)}</span>`,
    j.language && `<span class="tag" style="background:var(--lilac)">${esc(j.language)}</span>`,
  ].filter(Boolean).join('');
  const topics = Array.isArray(j.topics) ? j.topics : [];
  const tc = ['var(--yellow)', 'var(--pink)', 'var(--mint)', 'var(--sky)', 'var(--orange)', 'var(--lilac)'];
  $('topics').innerHTML = topics.map((t, i) => `<span style="background:${tc[i % tc.length]};transform:rotate(${i % 2 ? 2 : -2}deg)">${esc(t)}</span>`).join('');
  $('topicsWrap').classList.toggle('hide', !topics.length);
  $('modelTag').textContent = j.model || 'Gemini';
  $('modelNote').textContent = j.model ? `Model used for the last summary: ${j.model}${j.keyCount > 1 ? ` (key ${j.keyNumber} of ${j.keyCount})` : ''}.` : '';
}

/* ---------- main flow ---------- */
async function run(withAI) {
  const text = $('txt').value;
  const a = analyze(text);
  last = { a };
  renderLocal(a);
  if (!withAI) return;
  if (!a.words) { mood('sad', 'My plate is empty! Type or upload something.'); return; }
  const keys = getKeys();
  const key = keys[0];
  if (!key) {
    togglePanel(true);
    mood('sad', 'I need a Gemini API key first. Paste it up top!');
    return;
  }
  if (busy) return;
  busy = true;
  $('go').disabled = true;
  $('mood').innerHTML = '';
  $('topicsWrap').classList.add('hide');
  $('summary').innerHTML = '<div class="loading"><span class="dots"><i></i><i></i><i></i></span><span id="loadMsg">Gemini is reading…</span></div>';
  const lines = [`Chewing on ${fmt(a.words)} words…`, 'Counting syllables…', 'Asking Gemini nicely…', 'Almost there, I promise!'];
  let li = 0;
  mood('think', lines[0]);
  const timer = setInterval(() => { li = (li + 1) % lines.length; $('bubble').textContent = lines[li]; }, 1700);
  try {
    const j = await summarize({
      keys, usingBuiltInKey: !userKey, preferredModel: CFG.GEMINI_MODEL, text,
      length: document.querySelector('input[name=len]:checked').value,
      language: $('lang').value,
      onModel: (m, n, total) => { const el = $('loadMsg'); if (el) el.textContent = total > 1 && n > 1 ? `Gemini (${m}, backup key ${n - 1}) is reading…` : `Gemini (${m}) is reading…`; },
      onWait: s => { const el = $('loadMsg'); if (el) el.textContent = `Gemini is busy, trying again in ${s} seconds…`; $('bubble').textContent = 'Gemini is busy. Hang on a sec…'; },
    });
    clearInterval(timer);
    renderAI(j);
    mood('happy', `Yum! ${fmt(a.words)} words analyzed.`);
    confetti();
    toast('Analysis complete!');
    $('summary').closest('.card').scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
  } catch (e) {
    clearInterval(timer);
    console.error(e);
    $('summary').innerHTML = `<p class="empty">${esc(e.message || 'Something went wrong.')} The word stats and “Quick pick” summary still work without AI.</p>`;
    mood('sad', 'Uh oh, Gemini didn\'t answer. Details are in “The gist”.');
  }
  busy = false;
  $('go').disabled = false;
}

$('go').onclick = () => run(true);
$('clear').onclick = () => {
  $('txt').value = ''; $('fileInfo').textContent = '';
  $('summary').innerHTML = '<p class="empty">Hit <b>Analyze it!</b> and Gemini will write a summary here.</p>';
  $('mood').innerHTML = ''; $('topicsWrap').classList.add('hide');
  run(false); tab('text'); $('txt').focus();
  mood('idle', 'Fresh plate! Feed me something new.');
};
document.querySelectorAll('input[name=len]').forEach(r => r.onchange = () => last.a && renderLocal(last.a));
let tmr;
$('txt').addEventListener('input', () => { clearTimeout(tmr); tmr = setTimeout(() => run(false), 350); });
$('copy').onclick = async () => {
  const a = last.a;
  if (!a) return;
  const lines = ['TEXTLENS REPORT', `Words: ${a.words}`, `Unique words: ${a.unique}`, `Sentences: ${a.sents}`, `Paragraphs: ${a.paras}`,
    `Characters: ${a.chars} (${a.charsNoSp} without spaces)`, `Average word length: ${a.avgWord.toFixed(1)} letters`,
    `Average sentence length: ${a.avgSent.toFixed(1)} words`, `Reading time: ${mins(a.readMin)}`,
    `Reading ease: ${Math.max(0, Math.min(100, a.fre)).toFixed(0)}/100 (${readLabel(a.fre)})`, '', 'Top words:', ...a.top.map(([w, c], i) => `  ${i + 1}. ${w} (${c})`)];
  if (last.ai) {
    lines.push('', `SUMMARY (Gemini ${last.ai.model || ''}):`, last.ai.summary || '');
    if (last.ai.key_points) lines.push('', 'Key points:', ...last.ai.key_points.map(k => '- ' + k));
  } else lines.push('', 'QUICK PICK (no AI):', $('ext').textContent);
  try { await navigator.clipboard.writeText(lines.join('\n')); toast('Copied to clipboard!'); } catch (e) { toast('Your browser blocked copying'); }
};

$('txt').value = SAMPLE;
run(false);
if (!getKey()) mood('idle', 'Hi! Add your Gemini API key (top right), then feed me text.');
